const listSellerReturns = `-- name: ListSellerReturns :many
SELECT r.id, r.number, r.order_item_id, r.sub_order_id, r.buyer_id, r.seller_id, r.type, r.reason, r.note, r.status, r.reject_reason, r.decided_at, r.pickup_shipment_id, r.replacement_sub_order_id, r.refund_amount_paise, r.outcome_note, r.created_at, r.updated_at, i.product_name, i.variant_attrs, i.cover_key, i.qty, o.number AS order_number, o.id AS order_id, sh.awb
FROM return_requests r
JOIN order_items i ON i.id = r.order_item_id
JOIN sub_orders s ON s.id = r.sub_order_id
JOIN orders o ON o.id = s.order_id
LEFT JOIN shipments sh ON sh.id = r.pickup_shipment_id
WHERE r.seller_id = $1 AND ($2::text IS NULL OR r.status = $2::text)
ORDER BY r.created_at DESC LIMIT 200
`

