const setIssueStatus = `-- name: SetIssueStatus :one
UPDATE issues SET status = $1, updated_at = now(),
  first_response_at = CASE WHEN $2::bool AND first_response_at IS NULL THEN now() ELSE first_response_at END,
  resolved_at = CASE WHEN $1 = 'RESOLVED' THEN now() WHEN $1 = 'IN_PROGRESS' THEN NULL ELSE resolved_at END,
  closed_at = CASE WHEN $1 = 'CLOSED' THEN now() ELSE closed_at END
WHERE id = $3 RETURNING id, number, buyer_id, order_id, order_item_id, type, status, first_response_at, resolved_at, closed_at, created_at, updated_at
`

